// Preset-scoped routing. Read the same native World Info entries on every scan.
(() => {
  'use strict';
  const worldName = "新中市整合版（更新）", legacyWorldName = "新中市个人删减版（更新）";
  const sourceKeys = ["globalLore","characterLore","chatLore","personaLore"];
  const routes = [18,20,1996,2071,2232,2234,2284,2285,2348,2467,2515,2635,3063,3672,3673,3674,3675,3676,3801,3802,3804,3805,3806,3807,3808,3813,3822,3823,3882,4135,2243,3824,4063].map(uid => ({uid, promptId:'xzs-world-rule-'+uid, outlet:'XZS_RULE_'+uid}));
  function routeWorldRules(sources, preset) {
    const hasNew = sourceKeys.some(key => sources?.[key]?.some(entry => entry.world === worldName));
    const activeWorldName = hasNew ? worldName : legacyWorldName;
    if (hasNew) for (const key of sourceKeys) {
      if (Array.isArray(sources?.[key])) sources[key] = sources[key].filter(entry => entry.world !== legacyWorldName);
    }
