  eventOn(tavern_events.GENERATION_ENDED, clearPending);
  for (const name of ['CHAT_CHANGED', 'PRESET_CHANGED', 'OAI_PRESET_CHANGED_AFTER', 'GENERATION_STOPPED']) {
    if (tavern_events[name]) eventOn(tavern_events[name], () => { clearPending(); issued = null; });
